import {topics,formulas,scenarios,chains,sources} from './data/content.js';
import {questions,typeNames} from './data/questions.js';
import {load,shuffle,grade,topicProgress,stats,makeExam,dueCards,rateCard,labModel,esc} from './lib/core.js';

const $=s=>document.querySelector(s),main=$('#main'),root=document.documentElement;
let state=load({getItem:k=>localStorage.getItem(k)}),route=[],practice={topic:'all',type:'all',mode:'all',queue:[],index:0,answer:null,feedback:null,orders:{}},cards={topic:'all',mode:'due',index:0,flip:false},lab={tab:'zins',rate:3,scenario:0,revealed:false,direction:'restriktiv',order:null,checked:false,instrument:'kauf'},examIndex=0;
const icons={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',lernen:'M4 4h7l1 2 1-2h7v16h-7l-1 1-1-1H4zM12 6v14',uebung:'m5 13 4 4L20 6M4 4h5M4 21h16',labor:'M8 3h8M10 3v7L4 20q0 1 2 1h12q2 0 2-1l-6-10V3M8 15h8',klausur:'M8 4H4v17h16V4h-4M8 2h8v5H8zM8 12h8M8 16h5',karten:'M5 4h14v16H5zM2 7v16h14M9 9h6M9 13h4',glossar:'M4 4h16v16H4zM8 4v16M12 9h4M12 13h4',produkte:'M12 3v7M12 14v7M3 12h7M14 12h7M9 9h6v6H9z',organe:'M3 9h18L12 3zM5 10v9M10 10v9M15 10v9M20 10v9M3 21h18',ausrichtung:'m3 16 6-6 4 3 8-9M16 4h5v5',instrumente:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',preisstabilitaet:'M12 3v18M5 7h14M7 7l-4 7h8zm10 0-4 7h8zM8 21h8',transmission:'M3 5h5v5H3zM16 14h5v5h-5zM8 7h10v7M10 5l3 2-3 2',unabhaengigkeit:'M12 2 21 6v6q-1 7-9 10-8-3-9-10V6zM8 12l3 3 5-6'};
const icon=id=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[id]||icons.lernen}"/></svg>`;
const button=(text,action,primary=false,extra='')=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,to,primary=false)=>`<a class="button ${primary?'primary':''}" href="${to}">${text}</a>`;
const topicOptions=(value,all=true)=>(all?'<option value="all">Alle sechs Themen</option>':'')+topics.map(t=>`<option value="${t.id}" ${value===t.id?'selected':''}>${t.short}</option>`).join('');
const topic=id=>topics.find(t=>t.id===id),question=id=>questions.find(q=>q.id===id),fmt=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(n);
const deck=topics.flatMap(t=>t.terms.map(([front,back],i)=>({id:`${t.id}-${i}`,topic:t.id,front,back})));
function save(){try{localStorage.setItem('weiter-geldpolitik-v1',JSON.stringify(state));$('#storage-warning').hidden=true}catch{$('#storage-warning').textContent='Der Browser blockiert die Speicherung oder der Speicher ist voll. Fortschritte bleiben nur bis zum Schließen dieser Seite erhalten.';$('#storage-warning').hidden=false}}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2700)}
function appearance(){root.dataset.theme=state.theme;root.dataset.design=state.design;$('#theme').textContent=state.theme==='dark'?'Light Mode':'Dark Mode'}appearance();
function totalProgress(){return Math.round(topics.reduce((s,t)=>s+topicProgress(t.id,state,questions),0)/topics.length)}
function syncNav(){const active=route[0]||'dashboard',s=stats(null,state,questions);$('#nav').innerHTML=[['dashboard','Übersicht'],['lernen','Lernmodule'],['uebung','Übungsraum'],['labor','Geldpolitik-Labor'],['klausur','Klausursimulator'],['karten','Karteikarten'],['glossar','Glossar & Formeln'],['produkte','Mindmap & Forderungen']].map(([id,name])=>`<a class="nav-item ${id===active?'active':''}" href="#${id}" ${id===active?'aria-current="page"':''}>${icon(id)}<span>${name}</span>${id==='uebung'&&s.wrong.length?`<span class="count">${s.wrong.length}</span>`:''}</a>`).join('');$('#side-percent').textContent=totalProgress()+' %';$('#side-progress').style.width=totalProgress()+'%';$('#crumb').textContent=({dashboard:'Übersicht',lernen:'Lernmodule',uebung:'Übungsraum',labor:'Labor',klausur:'Klausur',karten:'Karteikarten',glossar:'Glossar',produkte:'Handlungsprodukte',quellen:'Material & Quellen',aufgabe:'Übungsraum',fehler:'Fehlerübersicht'})[active]||'Lernstudio'}
function heading(kicker,title,desc='',aside=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${aside}</div>`}
function topicRows(){return `<div class="topic-list">${topics.map((t,i)=>{const p=topicProgress(t.id,state,questions);return `<a class="topic-row" href="#lernen/${t.id}"><span class="topic-icon">${icon(t.id)}</span><div><h3>${t.short}</h3><p>${t.time} Min. lesen · ${questions.filter(q=>q.topic===t.id).length} Aufgaben</p></div><div class="pct">${p} %<div class="track"><i style="width:${p}%"></i></div></div><span class="checkmark">${state.read.includes(t.id)?'✓':'–'}</span></a>`}).join('')}</div>`}
function dashboard(){const s=stats(null,state,questions),p=totalProgress(),last=topic(state.last)||topics.find(t=>!state.read.includes(t.id))||topics[0],known=Object.values(state.cards).filter(x=>x.rating==='known').length;const doneTopics=topics.map(t=>({...t,s:stats(t.id,state,questions)})).filter(t=>t.s.attempted>=3);const strengths=doneTopics.filter(t=>t.s.correct/t.s.attempted>=.75),weak=doneTopics.filter(t=>t.s.correct/t.s.attempted<.6);return heading('DEIN LERNRAUM / GELDPOLITIK','Verstehen, was Geld bewegt.','Sechs Themen. Ein klarer Lernweg. Bereit für deine VWL-Klausur.',`<span class="pill">Lerngebiet 7 · Klasse 13</span>`)+`
<div class="dashboard-top"><section class="panel continue-panel"><div><div class="panel-head">${state.last?'ZULETZT BEARBEITET':'DEIN NÄCHSTER SCHRITT'}</div><h2>${last.title}</h2><p>${last.subtitle}</p></div><div class="actions">${link(state.last?'Lernen fortsetzen':'Mit dem Lernen beginnen','#lernen/'+last.id,true)}<span class="muted small">${last.time} Min. Lesezeit</span></div></section><section class="panel progress-panel" aria-label="Gesamtfortschritt ${p} Prozent"><div class="ring"><svg viewBox="0 0 140 140" aria-hidden="true"><circle cx="70" cy="70" r="60" stroke="var(--line)"/><circle cx="70" cy="70" r="60" stroke="var(--teal)" stroke-dasharray="${p*3.77} 377" stroke-linecap="round"/></svg><strong>${p}<span style="font-size:1rem"> %</span></strong></div><div class="progress-info"><h3>Schritt für Schritt.</h3><p>${state.read.length} von 6 Modulen gelesen<br>${s.correct} von ${questions.length} Aufgaben vollständig gelöst</p><span class="legend">50 % Lesen · 50 % Aufgaben<br>Offene Antworten: Selbsteinschätzung</span></div></section></div>
<div class="metrics"><div class="metric"><span class="metric-label">BEARBEITETE AUFGABEN</span><strong>${s.attempted}<span class="muted" style="font-size:1rem"> / ${questions.length}</span></strong><small>dein letzter Stand je Aufgabe</small></div><div class="metric"><span class="metric-label">NOCH EINMAL ÜBEN</span><strong>${s.wrong.length}</strong><small>Aufgaben mit offenen Punkten</small></div><div class="metric"><span class="metric-label">SICHERE KARTEIKARTEN</span><strong>${known}<span class="muted" style="font-size:1rem"> / ${deck.length}</span></strong><small>von dir als gewusst bewertet</small></div><div class="metric"><span class="metric-label">PROBEKLAUSUREN</span><strong>${state.exams.length}</strong><small>abgeschlossene Durchläufe</small></div></div>
<div class="dashboard-bottom"><section><div class="section-head"><h2>Dein Lernpfad</h2><span class="muted small">Die sechs Klausurthemen</span></div>${topicRows()}</section><aside><section class="lab-teaser"><div class="eyebrow">AUSPROBIEREN STATT AUSWENDIG</div><h3>Du drehst am Zins.<br>Was bewegt sich?</h3><svg class="mini-chart" viewBox="0 0 320 95" fill="none" aria-hidden="true"><path d="M0 75H320M0 40H320M0 5H320" stroke="var(--line)"/><path d="M0 16C45 16 45 16 76 38S125 37 151 53 197 50 220 67 275 74 320 81" stroke="var(--blue)" stroke-width="2.5"/><path d="M0 80C60 80 60 69 98 69S141 41 170 41 219 23 245 23 287 9 320 9" stroke="var(--teal)" stroke-width="2" stroke-dasharray="5 5"/></svg><p>Entdecke die Wirkung von Zinsen auf Kredite, Nachfrage und Inflationsdruck.</p>${link('Leitzinslabor öffnen','#labor/zins')}</section><section class="insights"><div class="section-head"><h3>Dein Lernkompass</h3></div>${!doneTopics.length?`<div class="empty"><b>Dein Start ist ein weißes Blatt.</b>Nach mindestens drei Aufgaben pro Thema erkennst du hier deine Stärken und deinen Übungsbedarf.</div>`:`<div class="insight"><strong>Das sitzt schon gut</strong><span>${strengths.length?strengths.map(t=>esc(t.short)).join(', '):'Noch kein Thema mit mindestens 75 % vollständig gelösten Aufgaben.'}</span></div><div class="insight"><strong>Hier lohnt sich Wiederholen</strong><span>${weak.length?weak.map(t=>esc(t.short)).join(', '):'Kein bearbeitetes Thema liegt unter 60 %.'}</span></div>`}<div class="actions">${link('Übungen starten','#uebung',true)}${s.wrong.length?link('Fehler ansehen','#fehler'):''}</div></section></aside></div>`}
function lesson(){const t=topic(route[1])||topics[0];try{localStorage.setItem('weiter-resume-v1:vwl-geldpolitik',JSON.stringify({site:'vwl-geldpolitik',chapter:t.id,title:t.short,course:'main',at:Date.now()}))}catch{}if(state.last!==t.id){state.last=t.id;save()}return `<div class="learn-layout"><nav class="module-nav" aria-label="Lernmodule">${topics.map((m,i)=>`<a href="#lernen/${m.id}" class="${t.id===m.id?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${m.short}${state.read.includes(m.id)?' ✓':''}</a>`).join('')}</nav><article class="lesson">${heading('LERNMODUL / '+(topics.indexOf(t)+1)+' VON 6',t.title,t.subtitle)}<div class="source-note">Materialbezug: ${t.source}</div><div class="term-grid">${t.terms.map(([a,b])=>`<div class="term"><b>${a}</b><p>${b}</p></div>`).join('')}</div>${t.sections.map(([h,p],i)=>`<section class="lesson-section"><h2>${h}</h2><p>${p}</p></section>${i===1?`<div class="callout"><div class="eyebrow">MERKSATZ</div><p>${t.remember}</p></div>`:''}`).join('')}<section class="example"><h3>Ein Beispiel aus der Wirtschaft</h3><p>${t.example}</p></section>${t.id==='ausrichtung'?policyTable():''}${t.id==='transmission'?chainHtml(chains.restriktiv):''}${t.id==='organe'?`<div class="callout"><div class="eyebrow">DAS SYSTEM IN EINEM SATZ</div><p>ESZB = EZB + alle EU-Zentralbanken<br>Eurosystem = EZB + Zentralbanken der Euro-Länder</p></div>`:''}<section class="summary"><h2>Das nimmst du mit</h2><p>${t.summary}</p><h3>Typische Klausurfrage</h3><p style="margin-top:12px">${t.exam}</p><details><summary>Verständnis prüfen: Kannst du den Merksatz erklären?</summary><p style="margin-top:15px">${t.remember} Nutze das Wirtschaftsbeispiel und erkläre jeden Zusammenhang in eigenen Worten. Vergleiche danach mit der Zusammenfassung und übe die Aufgaben dieses Moduls.</p></details></section><div class="actions">${button(state.read.includes(t.id)?'Als gelesen markiert · rückgängig':'Modul als gelesen markieren','read',true)}${link('Dieses Thema üben','#uebung/'+t.id)}${link('Nächstes Modul','#lernen/'+topics[(topics.indexOf(t)+1)%6].id)}</div></article></div>`}
function policyTable(){return `<div style="overflow:auto;margin:25px 0"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;padding:12px;border-bottom:1px solid var(--line)">Im Vergleich</th><th>Expansiv</th><th>Restriktiv</th></tr></thead><tbody>${[['Zinsimpuls','Senkung','Erhöhung'],['Neue Kredite','tendenziell günstiger','tendenziell teurer'],['Nachfrage','wird eher gestützt','wird eher gedämpft'],['Inflationsdruck','kann steigen','kann nachlassen'],['Risiko','Inflation / schwache Reaktion','Wachstums- / Beschäftigungsverluste']].map(r=>`<tr>${r.map(x=>`<td style="padding:12px;border-bottom:1px solid var(--line);color:var(--muted)">${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function questionHTML(q,a,context='practice'){const name=context==='exam'?'exam-answer':'practice-answer';let h=`<div class="question-meta"><span class="pill blue">${topic(q.topic).short}</span><span class="pill">${typeNames[q.type]}</span><span class="pill">AFB ${q.afb} · Stufe ${q.difficulty}</span><span class="pill">${q.points} Punkte</span></div><h2 class="question-title">${q.type==='cloze'?'Ergänzen Sie die Lücken.':esc(q.prompt)}</h2>`;
 if(q.type==='mc'){const options=getOptions(q,context);h+=`<fieldset style="border:0;padding:0;margin:0"><legend class="small muted">Eine Antwort ist richtig.</legend><div class="options" style="margin-top:10px">${options.map(i=>`<label class="option"><input type="radio" name="${name}" value="${i}" ${a===i?'checked':''}><span>${esc(q.options[i])}</span></label>`).join('')}</div></fieldset>`}
 if(q.type==='tf'){h+=`<fieldset style="border:0;padding:0;margin:0"><legend class="small muted">Bewerten Sie die Aussage.</legend><div class="options" style="margin-top:10px">${[true,false].map(v=>`<label class="option"><input type="radio" name="${name}" value="${v}" ${a===v?'checked':''}><span>${v?'Richtig':'Falsch'}</span></label>`).join('')}</div></fieldset><div class="field tf-note"><label for="reason">Begründung / Korrektur in eigenen Worten (wird nicht automatisch bewertet)</label><textarea id="reason" data-reason="${context}">${esc(context==='exam'?state.exam?.reasons?.[q.id]||'':practice.reason||'')}</textarea></div>`}
 if(q.type==='cloze'){let i=0;h+=`<div class="cloze-line">${q.prompt.split('___').map((p,j)=>`${j?`<input aria-label="Lücke ${++i}" data-blank="${i-1}" value="${esc(a?.[i-1]||'')}" autocomplete="off">`:''}${esc(p)}`).join('')}</div>`}
 if(q.type==='match'){const values=getPairs(q,context);h+=q.pairs.map(([term,def],i)=>`<div class="pair"><label for="pair-${i}">${esc(term)}</label><select id="pair-${i}" data-pair="${i}"><option value="">Bitte zuordnen</option>${values.map(v=>`<option ${a?.[i]===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></div>`).join('')}
 if(q.type==='connect'){const values=getPairs(q,context);h+=`<p class="small muted">Wähle links einen Begriff und danach rechts seine Definition. Die Nummern zeigen deine Verbindungen. Erneutes Verbinden ist möglich.</p><div class="connect-grid"><div>${q.pairs.map(([term],i)=>`<button class="connect-term ${connectLeft===i?'selected':''}" data-connect-left="${i}" aria-pressed="${connectLeft===i}"><b>${i+1}</b> ${esc(term)}<small>${a?.[i]?'verbunden':'noch offen'}</small></button>`).join('')}</div><div>${values.map((def,i)=>`<button class="connect-term" data-connect-right="${i}"><b>${a?.includes(def)?a.indexOf(def)+1:'–'}</b> ${esc(def)}</button>`).join('')}</div></div>`}
 if(q.type==='order'){const items=a||initialOrder(q,context);h+=`<p class="small muted">Mit „Schritt nach oben“ und „Schritt nach unten“ ordnen. Auch per Tastatur bedienbar.</p><ol class="order-list">${items.map((x,i)=>`<li><span>${esc(x)}</span><button data-move="${i}" data-dir="-1" aria-label="Schritt ${i+1} nach oben" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-dir="1" aria-label="Schritt ${i+1} nach unten" ${i===items.length-1?'disabled':''}>↓</button></li>`).join('')}</ol>`}
 if(q.type==='open')h+=`<label class="small muted" for="written">Deine ausformulierte Antwort</label><textarea id="written" style="margin-top:10px" data-written="${context}" placeholder="Verwende Fachbegriffe und begründe die Zusammenhänge …">${esc(a||'')}</textarea>${context==='practice'?'<p class="grading-note">Offene Antworten werden anhand einer Musterlösung von dir selbst bewertet. Es findet keine automatische Textbewertung statt.</p>':''}`;
 return h;
}
let connectLeft=null;
const optionCache={},pairCache={};
function getOptions(q,c){if(c==='exam')return state.exam.options[q.id];return optionCache[q.id]??=shuffle(q.options.map((_,i)=>i))}
function getPairs(q,c){if(c==='exam')return state.exam.pairs[q.id];return pairCache[q.id]??=shuffle(q.pairs.map(p=>p[1]))}
function initialOrder(q,c){if(c==='exam')return state.exam.orders[q.id];return practice.orders[q.id]??=nonTrivialShuffle(q.items)}
function nonTrivialShuffle(items){const a=shuffle(items);return JSON.stringify(a)===JSON.stringify(items)?[...a.slice(1),a[0]]:a}
function ensurePractice(){if(practice.queue.length)return;resetPractice()}
function resetPractice(){let qs=questions.filter(q=>(practice.topic==='all'||q.topic===practice.topic)&&(practice.type==='all'||q.type===practice.type)&&(practice.mode!=='wrong'||state.answers[q.id]?.score<q.points));practice.queue=shuffle(qs).map(q=>q.id);practice.index=0;practice.answer=null;practice.feedback=null;practice.reason=''}
function practiceScreen(){ensurePractice();const q=question(practice.queue[practice.index]);return heading('AKTIV ERINNERN','Dein Übungsraum','Begründen, verbinden, anwenden. Jede Antwort bringt dich einen Schritt weiter.')+`<div class="filterbar"><div class="field"><label for="practice-topic">Themenbereich</label><select id="practice-topic">${topicOptions(practice.topic)}</select></div><div class="field"><label for="practice-type">Aufgabenformat</label><select id="practice-type"><option value="all">Alle Formate</option>${Object.entries(typeNames).map(([id,n])=>`<option value="${id}" ${practice.type===id?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="practice-mode">Aufgabenauswahl</label><select id="practice-mode"><option value="all" ${practice.mode==='all'?'selected':''}>Alle Aufgaben</option><option value="wrong" ${practice.mode==='wrong'?'selected':''}>Fehler wiederholen</option></select></div>${button('Neu mischen','practice-shuffle')}</div>${q?`<section class="question-panel panel"><div class="section-head"><span class="mono muted small">Aufgabe ${practice.index+1} / ${practice.queue.length}</span>${button('Andere Aufgabe','practice-next',false,'class="small"')}</div>${questionHTML(q,practice.answer)}${practice.feedback?feedbackHTML(q):`<div class="actions">${button(q.type==='open'?'Mit Musterlösung vergleichen':'Antwort prüfen','practice-check',true)}</div>`}</section>`:`<div class="panel empty"><b>Hier ist gerade nichts zu wiederholen.</b>Wähle einen anderen Filter oder bearbeite neue Aufgaben.</div>`}`}
function solutionText(q){if(q.type==='mc')return q.options[q.correct];if(q.type==='tf')return q.correct?'Richtig':'Falsch';if(q.type==='cloze')return q.answers.map(x=>x[0]).join(' / ');if(q.type==='match'||q.type==='connect')return q.pairs.map(p=>p.join(': ')).join(' · ');if(q.type==='order')return q.items.join(' → ');return q.solution}
function rubricHTML(q,values=[],prefix='rubric'){return `<p class="grading-note">Selbstbewertung pro Kriterium: 0 = fehlt/falsch · 1 = teilweise · 2 = vollständig und fachlich richtig. Bewerte deine ursprüngliche Antwort.</p><div class="rubric">${q.criteria.map((c,i)=>`<div class="rubric-row"><label for="${prefix}-${q.id}-${i}">${esc(c)}</label><select id="${prefix}-${q.id}-${i}" data-rubric="${i}" data-q="${q.id}"><option value="">Punkte</option>${[0,1,2].map(v=>`<option value="${v}" ${values[i]===v?'selected':''}>${v} / 2</option>`).join('')}</select></div>`).join('')}</div>`}
function feedbackHTML(q){if(q.type==='open')return `<div class="solution"><h3>Musterlösung</h3><p>${esc(q.solution)}</p>${rubricHTML(q,practice.rubric)}<div class="actions">${button('Selbsteinschätzung speichern','practice-self',true)}${button('Nächste Aufgabe','practice-next')}</div></div>`;const pts=practice.feedback.score;return `<div class="feedback ${pts===q.points?'':'bad'}" role="status"><h3>${pts===q.points?'Richtig gelöst.':'Schau dir den Zusammenhang noch einmal an.'} ${pts} / ${q.points} Punkte</h3><p><strong>Lösung:</strong> ${esc(solutionText(q))}</p><p style="margin-top:10px">${esc(q.explanation)}</p>${q.type==='tf'?'<p style="margin-top:10px">Vergleiche deine Begründung mit dieser Erklärung. Automatisch bewertet wurde nur Richtig/Falsch.</p>':''}</div><div class="actions">${button('Nächste Aufgabe','practice-next',true)}${link('Im Modul nachlesen','#lernen/'+q.topic)}</div>`}
function recordAnswer(q,score,self=false){state.answers[q.id]={score,points:q.points,self,at:Date.now(),attempts:(state.answers[q.id]?.attempts||0)+1};save();syncNav()}
function errorScreen(){const s=stats(null,state,questions);return heading('DEIN FEHLERSPEICHER','Hier wächst dein Verständnis.','Angezeigt wird die jeweils letzte Bewertung einer Aufgabe. Offene Antworten beruhen auf deiner Selbsteinschätzung.')+`<div class="actions" style="margin:0 0 25px">${button('Alle Fehler wiederholen','all-errors',true)}${link('Alle Übungen','#uebung')}</div><div class="error-list">${s.wrong.length?s.wrong.map(q=>`<a href="#aufgabe/${q.id}">${esc(q.prompt)}<span>${topic(q.topic).short} · ${state.answers[q.id].score} / ${q.points} Punkte · ${q.type==='open'?'selbst bewertet':typeNames[q.type]}</span></a>`).join(''):'<p class="empty">Keine Aufgaben mit offenen Punkten gespeichert. Neue Aufgaben findest du im Übungsraum.</p>'}</div>`}
function cardQueue(){let a=deck.filter(c=>cards.topic==='all'||c.topic===cards.topic);if(cards.mode==='due')a=dueCards(a,state);if(cards.mode==='hard')a=a.filter(c=>state.cards[c.id]&&state.cards[c.id].rating!=='known');return a}
function cardsScreen(){const queue=cardQueue();if(cards.index>=queue.length)cards.index=0;const c=queue[cards.index];return heading('WISSEN, DAS BLEIBT','Kleine Karten. Große Klarheit.','Erinnere dich zuerst selbst. Decke die Antwort auf und schätze dein Wissen ehrlich ein.')+`<div class="filterbar"><div class="field"><label for="card-topic">Themenbereich</label><select id="card-topic">${topicOptions(cards.topic)}</select></div><div class="field"><label for="card-mode">Kartenauswahl</label><select id="card-mode"><option value="due" ${cards.mode==='due'?'selected':''}>Heute fällig & neu</option><option value="hard" ${cards.mode==='hard'?'selected':''}>Schwierige Karten</option><option value="all" ${cards.mode==='all'?'selected':''}>Alle Karten</option></select></div></div><section class="flash-workspace">${c?`<div class="flash-count"><span>${topic(c.topic).short}</span><span>${cards.index+1} / ${queue.length}</span></div><button class="flash ${cards.flip?'flipped':''}" data-action="card-flip" aria-label="Karte umdrehen" aria-pressed="${cards.flip}"><span class="flash-inner" style="display:block"><span class="flash-face" ${cards.flip?'aria-hidden="true"':''}><small>BEGRIFF ERKLÄREN</small><b>${c.front}</b><small>Antippen oder Enter zum Aufdecken</small></span><span class="flash-face flash-back" ${!cards.flip?'aria-hidden="true"':''}><small>ERKLÄRUNG</small><b>${c.back}</b><small>Wie sicher warst du?</small></span></span></button><div class="actions flash-ratings">${button('Nicht gewusst','card-unknown',false,!cards.flip?'disabled':'')}${button('Unsicher','card-unsure',false,!cards.flip?'disabled':'')}${button('Gewusst','card-known',true,!cards.flip?'disabled':'')}</div><div class="actions" style="justify-content:center">${button('Karte überspringen','card-next')}</div>`:'<div class="panel empty"><b>Für diesen Filter bist du durch.</b>Du kannst alle Karten ansehen oder später zur fälligen Wiederholung zurückkommen.</div>'}<p class="grading-note">Wiederholung: Nicht gewusst nach 5 Minuten, unsicher nach 1 Tag, gewusst schrittweise nach 1, 3, 7, 14 und 30 Tagen. Die Auswahl „Schwierige Karten“ erlaubt auch frühere Wiederholung.</p></section>`}
function examScreen(){const ex=state.exam;if(ex?.phase==='running')return runningExam();if(ex?.phase==='review')return examReview(ex);return heading('GENERALPROBE','Deine Klausur beginnt hier.','Ein echter Durchlauf: ohne Hinweise, mit Zeitlimit und einer Auswertung am Ende.')+`<div class="exam-setup"><section class="panel exam-guide"><div class="eyebrow">12 AUFGABEN / 6 THEMEN</div><h2>Wissen zeigen.<br>Zusammenhänge erklären.</h2><p>Jede Klausur enthält sechs offene Fragen und sechs weitere Aufgaben. Die Auswahl wird für jeden Durchlauf neu zusammengestellt.</p><ul><li>Grundlagen: AFB I · Anwendung: AFB I und II · Analyse: AFB I, II und III.</li><li>Antworten werden während des Durchlaufs lokal gespeichert.</li><li>Erst nach Abgabe erhältst du Lösungen und Erklärungen.</li><li>Offene Fragen bewertest du danach selbst anhand konkreter Kriterien.</li></ul><p>Die Zeit läuft auch beim Verlassen oder Neuladen weiter. Nach Ablauf werden die gespeicherten Antworten automatisch abgegeben.</p></section><section class="panel exam-config"><h3 style="margin-bottom:22px">Dein Durchlauf</h3><div class="field"><label for="duration">Zeitlimit</label><input id="duration" type="number" min="1" max="180" step="1" value="60" aria-describedby="duration-help"><span id="duration-help" class="small muted">1–180 Minuten · Empfehlung: 60–90 Minuten</span></div><div class="field"><label for="difficulty">Anforderungsniveau</label><select id="difficulty"><option value="1">Grundlagen · AFB I</option><option value="2">Anwendung · bis AFB II</option><option value="3" selected>Analyse · bis AFB III</option></select></div>${button('Klausur starten','exam-start',true)}<p class="grading-note">Keine offizielle Note. Die Auswertung ist ein Lerninstrument. Eigene Bewertungen werden ausdrücklich gekennzeichnet.</p></section></div>${state.exams.length?`<section style="margin-top:35px"><h2>Bisherige Durchläufe</h2><div class="error-list">${[...state.exams].reverse().map(e=>`<a href="#ergebnis/${e.id}">${new Date(e.ended).toLocaleDateString('de-DE')} · ${e.minutes} Minuten<span>${examScoreLabel(e)}</span></a>`).join('')}</div></section>`:''}`}
function examScore(e){let points=0,total=0,pending=0;for(const id of e.ids){const q=question(id);total+=q.points;if(q.type==='open'){const r=e.rubrics?.[id];if(!r||r.some(x=>!Number.isInteger(x))||r.length!==q.criteria.length)pending++;else points+=r.reduce((a,b)=>a+b,0)}else points+=grade(q,e.answers[id])||0}return {points,total,pending}}
function examScoreLabel(e){const s=examScore(e);return s.pending?`${s.points} / ${s.total} Punkte vorläufig · ${s.pending} offene Selbstbewertungen`:`${s.points} / ${s.total} Punkte · ${Math.round(s.points/s.total*100)} % · inkl. Selbsteinschätzung`}
function runningExam(){const e=state.exam,q=question(e.ids[examIndex]);return `<div class="exam-header"><div><div class="eyebrow" style="margin:0">KLAUSUR LÄUFT</div><span class="small muted">Aufgabe ${examIndex+1} von ${e.ids.length}</span></div><span class="timer" id="timer" role="timer" aria-label="Verbleibende Zeit">${timeLeft(e)}</span>${button('Abgeben','exam-confirm')}</div><div class="exam-pager" aria-label="Aufgabennavigation">${e.ids.map((id,i)=>`<button data-exam-index="${i}" class="${i===examIndex?'current':''} ${answered(e.answers[id])?'answered':''}" aria-label="Aufgabe ${i+1}${answered(e.answers[id])?', bearbeitet':''}" ${i===examIndex?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><section class="exam-question panel" style="margin-top:25px">${questionHTML(q,e.answers[q.id],'exam')}<div class="actions">${button('Vorherige Aufgabe','exam-prev',false,examIndex===0?'disabled':'')}${button(examIndex===e.ids.length-1?'Zur Abgabe':'Nächste Aufgabe',examIndex===e.ids.length-1?'exam-confirm':'exam-next',true)}</div><div id="submit-confirm" hidden class="confirm-panel"><h3>Klausur abgeben?</h3><p>Du hast ${e.ids.filter(id=>answered(e.answers[id])).length} von ${e.ids.length} Aufgaben bearbeitet. Danach werden die Musterlösungen sichtbar.</p><div class="actions">${button('Jetzt abgeben','exam-submit',true)}${button('Weiterarbeiten','exam-cancel-submit')}</div></div></section>`}
function answered(a){return Array.isArray(a)?a.some(v=>v!==''&&v!==undefined):a!==undefined&&a!==null&&String(a).trim()!==''}
function timeLeft(e){const s=Math.max(0,Math.ceil((e.deadline-Date.now())/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function finishExam(timed=false){const e=state.exam;if(!e||e.phase!=='running')return;e.phase='review';e.ended=Date.now();e.timed=timed;e.rubrics={};e.ids.forEach(id=>{const q=question(id);if(q.type!=='open')recordAnswer(q,grade(q,e.answers[id])||0)});state.exams.push(e);state.exams=state.exams.slice(-50);save();render();toast(timed?'Zeit abgelaufen. Deine gespeicherten Antworten wurden abgegeben.':'Klausur abgegeben. Vergleiche jetzt deine Antworten.')}
function examReview(e){const s=examScore(e);const missingTopics=topics.map(t=>{const qs=e.ids.map(question).filter(q=>q.topic===t.id),total=qs.reduce((a,q)=>a+q.points,0),points=qs.reduce((a,q)=>a+(q.type==='open'?(e.rubrics?.[q.id]||[]).reduce((a,b)=>a+(b||0),0):grade(q,e.answers[q.id])||0),0);return {...t,total,points}}).filter(t=>t.points/t.total<.7);return `<section class="exam-result">${heading('DEINE AUSWERTUNG','Hier liegt dein nächster Schritt.',e.timed?'Das Zeitlimit ist abgelaufen. Ausgewertet werden deine zuletzt gespeicherten Antworten.':'Lösungen verstehen, offene Antworten einschätzen und gezielt weiterlernen.')}<div class="panel"><div class="result-metrics"><div><strong>${s.points} / ${s.total}</strong><span>${s.pending?'vorläufige Punkte':'Gesamtpunkte inkl. Selbstbewertung'}</span></div><div><strong>${s.pending?'offen':Math.round(s.points/s.total*100)+' %'}</strong><span>${s.pending?`${s.pending} offene Bewertungen ausstehend`:'Ergebnis inkl. Selbstbewertung'}</span></div><div><strong>${Math.max(1,Math.round((e.ended-e.started)/60000))} Min.</strong><span>von ${e.minutes} Minuten</span></div></div><p class="grading-note">Geschlossene Aufgaben sind automatisch ausgewertet. Bei offenen Aufgaben wählst du pro Kriterium 0, 1 oder 2 Punkte. Erst nach vollständiger Selbstbewertung gibt es einen Gesamtprozentwert. Dies ist keine automatische Bewertung deines Textes.</p></div>${e.ids.map((id,i)=>{const q=question(id),points=q.type==='open'?(e.rubrics?.[id]||[]).reduce((a,b)=>a+(b||0),0):grade(q,e.answers[id])||0;return `<details><summary>Aufgabe ${i+1} · ${topic(q.topic).short} · ${points} / ${q.points} Punkte${q.type==='open'?' (Selbsteinschätzung)':''}</summary><div class="question-meta" style="margin-top:20px"><span class="pill">${typeNames[q.type]} · AFB ${q.afb}</span></div><p>${esc(q.prompt)}</p><strong>Deine Antwort</strong><div class="review-answer">${esc(answerLabel(q,e.answers[id]))}</div>${q.type==='tf'&&e.reasons?.[id]?`<p><strong>Deine Begründung:</strong> ${esc(e.reasons[id])}</p>`:''}<h3>Musterlösung</h3><p style="margin-top:12px;color:var(--muted)">${esc(solutionText(q))}</p>${q.type!=='open'?`<p class="muted">${esc(q.explanation)}</p>`:rubricHTML(q,e.rubrics?.[id]||[],'exam-rubric')}</details>`}).join('')}<section style="margin-top:32px"><h2>${s.pending?'Vorläufige Lernempfehlung':'Deine Lernempfehlung'}</h2><p class="muted" style="margin-top:14px">${s.pending?'Noch nicht bewertete Antworten zählen in der Empfehlung vorläufig als offen. Vervollständige zuerst deine Selbsteinschätzung.':'Themen unter 70 % der möglichen Punkte verdienen eine weitere Runde.'}</p><div class="actions">${missingTopics.length?missingTopics.map(t=>link(t.short,'#lernen/'+t.id)).join(''):'<span class="muted">Alle Themen mindestens zu 70 % gelöst. Wiederhole die unsicheren Begründungen.</span>'}</div></section><div class="actions">${button('Neue Klausur vorbereiten','exam-new',true)}${link('Fehler gezielt üben','#fehler')}</div></section>`}
function answerLabel(q,a){if(a===undefined||a===null||a==='')return 'Keine Antwort gespeichert.';if(q.type==='mc')return q.options[a]||'Keine Antwort';if(q.type==='tf')return a?'Richtig':'Falsch';if(q.type==='match'||q.type==='connect')return q.pairs.map((p,i)=>`${p[0]}: ${a[i]||'nicht zugeordnet'}`).join('\n');return Array.isArray(a)?a.map(x=>x||'–').join(q.type==='order'?' → ':' / '):a}
function chainHtml(items){return `<div class="chain">${items.map((x,i)=>`<div class="chain-node" style="animation-delay:${i*.07}s">${esc(x)}</div>`).join('')}</div>`}
function laborScreen(){const active=route[1]||lab.tab;lab.tab=['zins','szenario','kette','instrumente'].includes(active)?active:'zins';return heading('DEIN GELDPOLITIK-LABOR','Zusammenhänge sichtbar machen.','Verändere eine Entscheidung und verfolge die möglichen Folgen.')+`<div class="tabs" aria-label="Simulationen">${[['zins','Leitzinslabor'],['szenario','Restriktiv oder expansiv?'],['kette','Wirkungsketten'],['instrumente','Instrumente im System']].map(([id,n])=>`<a class="button tab ${lab.tab===id?'active':''}" href="#labor/${id}" ${lab.tab===id?'aria-current="page"':''}>${n}</a>`).join('')}</div>${lab.tab==='zins'?rateLab():lab.tab==='szenario'?scenarioLab():lab.tab==='kette'?chainLab():instrumentLab()}`}
function rateLab(){const m=labModel(lab.rate);return `<div class="lab-layout"><section class="panel lab-controls"><div class="eyebrow">MODELLHAFTER LEITZINS</div><output class="big-rate" id="lab-rate">${fmt(lab.rate)} %</output><label for="rate" class="small muted">Zins verändern und Auswirkungen beobachten</label><input id="rate" type="range" min="0" max="6" step="0.25" value="${lab.rate}" aria-valuetext="${fmt(lab.rate)} Prozent"><div class="range-labels"><span>0 % · lockerer</span><span>6 % · straffer</span></div><p>Vergleiche mit dem frei gewählten Ausgangspunkt von 3 %. Unterhalb wird die Modellnachfrage gestützt, oberhalb gedämpft. Die Zahlen sind keine aktuellen EZB-Zinsen.</p>${button('Auf 3 % zurücksetzen','lab-reset')}</section><section class="panel"><div class="section-head"><h3>Was könnte sich verändern?</h3><span class="pill">Illustration</span></div><div id="lab-bars">${labBars(m)}</div></section></div><div class="model-note"><strong>Ein bewusst vereinfachtes Modell.</strong> Kredit- und Sparzinsen sind fiktive Beispielwerte. Alle übrigen Größen sind frei gewählte Richtungsindizes (Ausgangspunkt = 100), keine Prozentprognosen. Beispielgleichungen: Kreditzins = 5 + 0,8 × (Modellleitzins − 3); Nachfrageindex = 100 − 7 × (Modellleitzins − 3). Die Koeffizienten sind didaktisch gewählt, nicht empirisch geschätzt. Verzögerungen, Angebotsschocks und Erwartungen werden nicht berechnet.</div><div id="lab-chain">${chainHtml(lab.rate>3?chains.restriktiv:lab.rate<3?chains.expansiv:['Ausgangspunkt: Modellleitzins 3 %','Fiktive Kredit- und Sparzinsen','Alle Nachfrageindizes stehen bei 100'])}</div>`}
function labBars(m){return `<div class="bar-chart">${[['Kreditzins',m.credit,8,'%','var(--blue)'],['Sparzins',m.saving,8,'%','var(--blue)'],['Kreditnachfrage',m.loan,150,'','var(--teal)'],['Investitionen',m.investment,150,'','var(--teal)'],['Konsum',m.consumption,150,'','var(--teal)'],['Gesamtnachfrage',m.demand,150,'','var(--teal)'],['Inflationsdruck',m.pressure,150,'','var(--amber)']].map(([name,val,max,unit,color])=>`<div class="bar-row"><span>${name}</span><div class="bar"><i style="width:${val/max*100}%;background:${color}"></i></div><output>${fmt(val)}${unit}</output></div>`).join('')}</div>`}
function scenarioLab(){const s=scenarios[lab.scenario];return `<section class="panel" style="max-width:980px"><div class="section-head"><span class="eyebrow" style="margin:0">FALL ${lab.scenario+1} / ${scenarios.length} · FIKTIVES SZENARIO</span>${button('Anderer Fall','scenario-next')}</div><h2>${s.title}</h2><p class="scenario-copy">${s.situation}</p><label for="scenario-reason" class="small muted">Welche Maßnahme wäre sinnvoll? Begründe deine Entscheidung.</label><textarea id="scenario-reason" style="margin:10px 0 20px" placeholder="Maßnahme, Ziel, Wirkung und mögliche Nebenwirkung …">${esc(lab.reason||'')}</textarea><div class="actions">${button('Restriktiv','scenario-restrict',true)}${button('Expansiv','scenario-expand')}</div>${lab.revealed?`<div class="feedback ${lab.choice===s.answer?'':'bad'}"><h3>${lab.choice===s.answer?'Deine Richtung passt zu dieser Modelllage.':'Prüfe deine Entscheidung anhand der Inflationsaussichten.'}</h3><p>${s.why}</p><p style="margin-top:12px">Vergleiche deine Begründung: Ausgangslage → Instrument → Finanzierung → Nachfrage → Inflationsdruck → Grenze. Deine freie Begründung wird nicht automatisch benotet.</p></div>${chainHtml(chains[s.answer])}`:''}</section>`}
function chainLab(){lab.order??=nonTrivialShuffle(chains[lab.direction]);return `<section style="max-width:950px"><div class="filterbar"><div class="field"><label for="chain-direction">Wirkungskette wählen</label><select id="chain-direction"><option value="restriktiv" ${lab.direction==='restriktiv'?'selected':''}>Restriktive Geldpolitik</option><option value="expansiv" ${lab.direction==='expansiv'?'selected':''}>Expansive Geldpolitik</option><option value="wechselkurs" ${lab.direction==='wechselkurs'?'selected':''}>Vertiefung · Wechselkurskanal</option></select></div>${button('Neu mischen','chain-shuffle')}</div><h2>Bringe Ursache und Wirkung zusammen.</h2><p class="muted" style="margin-top:15px">Ordne die Schritte mit den beiden Tasten. Alle Zusammenhänge sind modellhaft.</p><ol class="order-list">${lab.order.map((x,i)=>`<li><span>${x}</span><button data-chain-move="${i}" data-dir="-1" aria-label="Schritt ${i+1} nach oben" ${i===0?'disabled':''}>↑</button><button data-chain-move="${i}" data-dir="1" aria-label="Schritt ${i+1} nach unten" ${i===lab.order.length-1?'disabled':''}>↓</button></li>`).join('')}</ol><div class="actions">${button('Reihenfolge prüfen','chain-check',true)}</div>${lab.checked?`<div class="feedback ${JSON.stringify(lab.order)===JSON.stringify(chains[lab.direction])?'':'bad'}"><h3>${JSON.stringify(lab.order)===JSON.stringify(chains[lab.direction])?'Die Kette stimmt.':'Prüfe die Übergänge.'}</h3><p>Erkläre zu jedem Schritt, warum er den nächsten beeinflusst. Die Wirkung tritt nicht automatisch und nicht sofort ein.</p></div>${chainHtml(chains[lab.direction])}`:''}</section>`}
const instruments={kauf:{name:'Wertpapierkauf',flow:'Liquidität zuführen',bank:'Reserven steigen zunächst',customer:'Kreditangebot kann begünstigt werden',text:'Das Eurosystem kauft Wertpapiere gegen Zentralbankgeld. Das erhöht zunächst die Bankreserven und kann längerfristige Finanzierung erleichtern. Nachfrage, Eigenkapital und Risiken entscheiden mit über neue Kredite.'},verkauf:{name:'Wertpapierverkauf',flow:'Liquidität entziehen',bank:'Reserven sinken zunächst',customer:'Finanzierung kann straffer werden',text:'Beim endgültigen Verkauf werden Reserven des Bankensystems belastet. Das kann Finanzierungsbedingungen straffen. Ein proportionaler Rückgang privater Kredite ist daraus nicht abzuleiten.'},refi:{name:'Hauptrefinanzierung',flow:'Besicherter Kredit',bank:'Befristete Liquidität',customer:'Bankfinanzierung wird unterstützt',text:'Eine Geschäftsbank erhält Zentralbankgeld gegen geeignete Sicherheiten und zahlt es am Ende zurück. Reguläre Hauptrefinanzierung hat typischerweise eine Woche Laufzeit.'},einlage:{name:'Einlagesatz erhöhen',flow:'Anreiz / Zins',bank:'Übernachtanlage attraktiver',customer:'Kredite können teurer werden',text:'Ein höherer Einlagesatz beeinflusst Geldmarkt- und Bankkonditionen. Das ist ein Zinsimpuls; es wird dadurch nicht mechanisch eine feste Reserve- oder Kreditmenge abgezogen.'},reserve:{name:'Reservepflicht erhöhen',flow:'Zusätzliche Pflichtreserve',bank:'Mehr Reserven erforderlich',customer:'Finanzierungsbedingungen können straffer werden',text:'Ein hypothetisch höherer Mindestreservesatz bindet zusätzliches Reserveguthaben. Banken können weitere Liquidität beschaffen. Die Wirkung ist deshalb keine feste Obergrenze privater Kredite.'}};
function instrumentLab(){const x=instruments[lab.instrument];return `<div class="instrument-picks">${Object.entries(instruments).map(([id,x])=>`<button class="button ${lab.instrument===id?'active':''}" data-instrument="${id}">${x.name}</button>`).join('')}</div><div class="network"><div class="network-node"><strong>Eurosystem</strong><span>${x.flow}</span></div><span class="flow" aria-hidden="true">⇢</span><div class="network-node"><strong>Geschäftsbanken</strong><span>${x.bank}</span></div><span class="flow" aria-hidden="true">⇢</span><div class="network-node"><strong>Haushalte & Unternehmen</strong><span>${x.customer}</span></div></div><div class="callout"><div class="eyebrow">${x.name}</div><p>${x.text}</p></div><p class="model-note">Die Verbindung zeigt mögliche Wirkungen. Haushalte erhalten Bankkredite und Kundeneinlagen, keine Reservekonten bei der EZB. Die Pfeile stellen deshalb keine direkte Weitergabe von Reserven dar.</p>${link('Instrumente gründlich verstehen','#lernen/instrumente')}`}
function glossaryScreen(){return heading('ZUM NACHSCHLAGEN','Wörter werden zu Werkzeugen.','Fachbegriffe und Rechenwege aus den sechs Themen – mit unterstützendem Vorwissen.')+`<label for="glossary-search" class="small muted">Begriff, Thema oder Formel suchen</label><input type="search" id="glossary-search" class="search-input" placeholder="Zum Beispiel: Mindestreserve, Deflation, Realzins …" style="margin-top:10px"><div id="glossary-results">${glossaryResults('')}</div>`}
function glossaryResults(search){const needle=search.trim().toLocaleLowerCase('de'),entries=topics.flatMap(t=>t.terms.map(([term,definition])=>({term,definition,topic:t}))).filter(x=>(x.term+' '+x.definition+' '+x.topic.short).toLocaleLowerCase('de').includes(needle)),fs=formulas.filter(f=>(f.term+' '+f.formula+' '+f.note).toLocaleLowerCase('de').includes(needle));return `<p class="muted small" role="status" style="margin-top:15px">${entries.length} Begriffe · ${fs.length} Formeln</p><div class="glossary-list">${entries.map(e=>`<article class="glossary-item"><h3>${e.term}</h3><p>${e.definition}</p><a href="#lernen/${e.topic.id}" class="small">${e.topic.short}</a></article>`).join('')}${fs.map(f=>`<article class="glossary-item"><h3>${f.term}</h3><div class="formula">${f.formula}</div><p>${f.example}</p><p class="small">${f.note}</p></article>`).join('')}</div>${!entries.length&&!fs.length?'<p class="empty">Kein Treffer. Versuche einen kürzeren Suchbegriff.</p>':''}`}
function productsScreen(){return heading('DEINE HANDLUNGSPRODUKTE','Ordne deine Gedanken.','Mindmap und Forderungskatalog aus der Checkliste – als eigene, lokal gespeicherte Arbeitsprodukte.')+`<div class="notes-layout"><section><h2 style="margin-bottom:20px">Deine Geldpolitik-Mindmap</h2><div class="mindmap"><h3>Geldpolitik der EZB</h3>${topics.map(t=>`<label>${t.short}<textarea data-note="map-${t.id}" placeholder="Kernbegriffe, Aufgaben, Zusammenhänge …">${esc(state.notes['map-'+t.id]||'')}</textarea></label>`).join('')}</div><p class="grading-note">Tipp: Verknüpfe Instrumente mit Wirkungsketten. Unter „Unabhängigkeit“ kannst du die Schutzmechanismen und ihre Grenzen sammeln.</p></section><section class="panel requirements"><h2>Dein Forderungskatalog</h2><p class="muted" style="margin-top:15px">Formuliere begründete Forderungen zur Preisstabilität. Trenne die Zuständigkeiten von EZB und Bundesregierung.</p>${[['situation','Ausgangslage'],['recipient','Adressat und Zuständigkeit'],['demand1','Forderung 1 mit Begründung'],['demand2','Forderung 2 mit Begründung'],['demand3','Forderung 3 mit Begründung'],['tradeoff','Zielkonflikt und Abwägung']].map(([id,label])=>`<div class="field"><label for="note-${id}">${label}</label><textarea id="note-${id}" data-note="${id}" style="min-height:90px">${esc(state.notes[id]||'')}</textarea></div>`).join('')}<details><summary>Qualitätscheck ansehen</summary><p class="grading-note">Ist der Adressat tatsächlich zuständig? Welche Ursache willst du beeinflussen? Erklärt die Begründung eine Wirkungskette? Berücksichtigst du Nebenwirkungen und die Unabhängigkeit der EZB?</p></details></section></div><div class="actions">${button('Arbeitsprodukte drucken / als PDF speichern','print',true)}${button('Lernstand als JSON sichern','export')}</div><p class="grading-note">Der Browserdruck enthält deine Arbeitsprodukte. Die JSON-Sicherung enthält zusätzlich Übungen, Karten und Klausuren. Alle Eingaben bleiben in diesem Browser, bis du sie exportierst.</p>`}
function sourcesScreen(){return `<article class="sources">${heading('MATERIAL & EINORDNUNG','Eine klare Grundlage.','Die Checkliste legt den Klausurstoff fest. Unterrichtsmaterial und ergänzendes Fachwissen bleiben erkennbar.')}<h2>Deine Unterrichtsmaterialien</h2><p>Primärquelle ist deine Datei „VWL 9.pdf“ mit 68 PDF-Seiten. Seitenangaben in dieser Anwendung beziehen sich auf die PDF-Reihenfolge, nicht auf gedruckte Buchseiten. Die Checkliste „Lerngebiet 7: Geldpolitik“ enthält die sechs Lernziele und die Handlungsprodukte Mindmap und Forderungskatalog.</p><ul><li>S. 2–13: Inflation, Warenkorb, Messung, Folgen und Forderungskatalog als Vorwissen.</li><li>S. 14–23, 26: Ziele, Leitzinsen, weitere Aufgaben und Bankenaufsicht.</li><li>S. 27–41: Instrumente, Fazilitäten, Wirkungsdiagramme, Tender und Übungsaufgaben.</li><li>S. 42–50: Unabhängigkeit, Organe, Zusammenfassung und Grenzen der gemeinsamen Geldpolitik.</li><li>S. 68: ergänzende handschriftliche Instrumentenübersicht.</li></ul><p>Außenhandel ab S. 54 und die Vertiefung zu alternativen Währungen sind kein zusätzliches Pflichtmodul dieser Anwendung. Externe Buchaufgaben ohne vollständige Aufgabenstellung wurden nicht als vermeintliche Originalaufgaben übernommen. Die Aufgaben hier sind eigenständig formuliert und an den Unterrichtsthemen orientiert.</p><h2>Fachliche Korrekturen und Ergänzungen</h2><ul><li>Das aktuelle Ziel lautet symmetrisch 2 % mittelfristig. Die ältere Formulierung „unter, aber nahe 2 %“ wird historisch eingeordnet.</li><li>Hauptrefinanzierungsgeschäfte haben regulär eine Woche Laufzeit; die ältere 14-Tage-Box der PDF ist nicht der heutige Standard.</li><li>Die Leitzinsen sind mehrere Zinssätze. Der Hauptrefinanzierungssatz und der für die Steuerung zentrale Einlagesatz werden unterschieden.</li><li>Schulmodelle über Bankreserven und Kreditangebot werden nicht als mechanischer Kreditmultiplikator dargestellt.</li><li>Die historische Zwei-Säulen-Darstellung in den Materialien wird nicht zum siebten Klausurthema gemacht. Die heutige EZB-Strategie integriert wirtschaftliche sowie monetäre und finanzielle Analysen.</li><li>Leitzinslabor und Szenarien verwenden fiktive Modellwerte. Aktuelle Zinssätze sind nur über die offizielle EZB-Tabelle verlinkt.</li></ul><h2>Offizielle Quellen zum Vertiefen</h2><p>Fachliche Gegenprüfung am 23. November 2026. Bei zeitabhängigen Angaben gilt die jeweils aktuelle Originalquelle.</p><ul>${sources.map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${title}</a></li>`).join('')}</ul><h2>Wie dein Fortschritt zählt</h2><p>Jedes Thema erhält bis zu 50 Prozentpunkte für „gelesen“ und bis zu 50 für vollständig gelöste Aufgaben. Der Gesamtwert ist der Mittelwert der sechs Themen. Die jeweils letzte Antwort zählt. Offene Fragen fließen anhand deiner Selbsteinschätzung ein. „Gelesen“ ist eine eigene Markierung und kein Nachweis fachlicher Beherrschung.</p><h2>Speicherung & Sicherung</h2><p>Die Anwendung verwendet localStorage ohne Konto, Analyse-Tracker oder Server für Lernantworten. Andere Browser und Geräte übernehmen deinen Stand nicht automatisch. Du kannst eine JSON-Sicherung exportieren und hier wieder einlesen. Ein Import ersetzt den lokalen Lernstand nach deiner Bestätigung.</p><div class="actions">${button('Lernstand sichern','export')}<label class="button" for="import-data">Sicherung einlesen</label><input id="import-data" type="file" accept="application/json,.json" hidden></div><div id="import-preview"></div><h2>Gestaltung</h2><p>Financial Dashboard ist der Standard. Das kontrastreiche Lernstudio greift Typografie und die Rücknavigation deiner Hauptplattform „weiter.“ auf. Alternativ stehen Interactive Learning Studio und Minimal Editorial Learning als echte Vorschau und anwendbare Gestaltung zur Verfügung.</p>${link('Alle drei Entwürfe vergleichen','designs.html')}</article>`}
function capture(q){if(q.type==='mc'){const input=$('input[name$="-answer"]:checked');return input?+input.value:null}if(q.type==='tf'){const input=$('input[name$="-answer"]:checked');return input?input.value==='true':null}if(q.type==='cloze')return [...main.querySelectorAll('[data-blank]')].map(x=>x.value);if(q.type==='connect')return route[0]==='klausur'?state.exam.answers[q.id]||Array(q.pairs.length).fill(''):practice.answer||Array(q.pairs.length).fill('');if(q.type==='match')return [...main.querySelectorAll('[data-pair]')].map(x=>x.value);if(q.type==='open')return $('#written')?.value||'';if(q.type==='order')return route[0]==='klausur'?state.exam.answers[q.id]||state.exam.orders[q.id]:practice.answer||practice.orders[q.id]}
function validAnswer(q,a){if(q.type==='order')return true;if(q.type==='mc'||q.type==='tf')return a!==null&&a!==undefined;if(q.type==='open')return String(a||'').trim().length>0;return a?.length&&a.every(v=>String(v).trim().length>0)}
function currentExam(){return route[0]==='ergebnis'?state.exams.find(e=>e.id===route[1]):state.exam}
function persistExamReview(e){const i=state.exams.findIndex(x=>x.id===e.id);if(i>=0)state.exams[i]=e;if(state.exam?.id===e.id)state.exam=e;save()}
function render(){if(state.exam?.phase==='running'&&Date.now()>=state.exam.deadline){finishExam(true);return}syncNav();const page=route[0]||'dashboard';if(page==='dashboard')main.innerHTML=dashboard();else if(page==='lernen')main.innerHTML=lesson();else if(page==='uebung'||page==='aufgabe')main.innerHTML=practiceScreen();else if(page==='fehler')main.innerHTML=errorScreen();else if(page==='karten')main.innerHTML=cardsScreen();else if(page==='klausur')main.innerHTML=examScreen();else if(page==='ergebnis'){const ex=state.exams.find(e=>e.id===route[1]);main.innerHTML=ex?examReview(ex):heading('NICHT GEFUNDEN','Dieser Durchlauf ist hier nicht gespeichert.','Klausurergebnisse liegen lokal im Browser.')+link('Zum Klausursimulator','#klausur')}else if(page==='labor')main.innerHTML=laborScreen();else if(page==='glossar')main.innerHTML=glossaryScreen();else if(page==='produkte')main.innerHTML=productsScreen();else if(page==='quellen')main.innerHTML=sourcesScreen();else main.innerHTML=heading('NICHT GEFUNDEN','Hier geht es zum Lernstudio.')+link('Zur Übersicht','#dashboard');if((page==='uebung'||page==='aufgabe')&&practice.feedback){main.querySelectorAll('.question-panel input,.question-panel textarea,.question-panel select:not([data-rubric]),.question-panel [data-move],.question-panel [data-connect-left],.question-panel [data-connect-right]').forEach(x=>x.disabled=true)}document.title=`${page==='lernen'?(topic(route[1])||topics[0]).short:$('#crumb').textContent} · Geldpolitik · weiter.`}
function navigate(){connectLeft=null;route=location.hash.slice(1).split('/').map(x=>{try{return decodeURIComponent(x)}catch{return x}});if(route[0]==='uebung'){practice.topic=topic(route[1])?route[1]:'all';resetPractice()}if(route[0]==='aufgabe'){const q=question(route[1]);if(q){practice.queue=[q.id];practice.index=0;practice.answer=null;practice.feedback=null;practice.reason=''}}$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0)}
window.addEventListener('hashchange',navigate);
document.addEventListener('input',e=>{const target=e.target;
 if(target.id==='rate'){lab.rate=+target.value;target.setAttribute('aria-valuetext',fmt(lab.rate)+' Prozent');$('#lab-rate').textContent=fmt(lab.rate)+' %';$('#lab-bars').innerHTML=labBars(labModel(lab.rate));$('#lab-chain').innerHTML=chainHtml(lab.rate>3?chains.restriktiv:lab.rate<3?chains.expansiv:['Ausgangspunkt: Modellleitzins 3 %','Fiktive Kredit- und Sparzinsen','Alle Nachfrageindizes stehen bei 100']);return}
 if(target.id==='glossary-search'){$('#glossary-results').innerHTML=glossaryResults(target.value);return}
 if(target.dataset.note){state.notes[target.dataset.note]=target.value;save();return}
 if(target.id==='scenario-reason'){lab.reason=target.value;return}
 if(target.dataset.reason){if(target.dataset.reason==='exam'){const e=state.exam,q=question(e.ids[examIndex]);e.reasons[q.id]=target.value;save()}else practice.reason=target.value;return}
 if(target.closest('.exam-question')&&state.exam?.phase==='running'){const e=state.exam,q=question(e.ids[examIndex]);e.answers[q.id]=capture(q);save();updatePager()}
});
function updatePager(){const e=state.exam;main.querySelectorAll('[data-exam-index]').forEach(b=>{const i=+b.dataset.examIndex;b.classList.toggle('answered',answered(e.answers[e.ids[i]]))})}
document.addEventListener('change',e=>{const x=e.target;
 if(x.id==='practice-topic'||x.id==='practice-type'||x.id==='practice-mode'){practice[x.id.split('-')[1]]=x.value;resetPractice();render()}
 if(x.id==='card-topic'||x.id==='card-mode'){cards[x.id.split('-')[1]]=x.value;cards.index=0;cards.flip=false;render()}
 if(x.id==='chain-direction'){lab.direction=x.value;lab.order=null;lab.checked=false;render()}
 if(x.dataset.rubric!==undefined){const q=question(x.dataset.q),i=+x.dataset.rubric,v=x.value===''?null:+x.value;if(route[0]==='klausur'||route[0]==='ergebnis'){const ex=currentExam();ex.rubrics[q.id]??=Array(q.criteria.length).fill(null);ex.rubrics[q.id][i]=v;if(ex.rubrics[q.id].every(Number.isInteger))recordAnswer(q,ex.rubrics[q.id].reduce((a,b)=>a+b,0),true);persistExamReview(ex);const openDetails=[...main.querySelectorAll('details')].map(d=>d.open);const scroll=window.scrollY;render();main.querySelectorAll('details').forEach((d,i)=>d.open=openDetails[i]);window.scrollTo(0,scroll)}else{practice.rubric??=Array(q.criteria.length).fill(null);practice.rubric[i]=v}}
 if(x.id==='import-data')previewImport(x.files?.[0]);
});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-move],[data-chain-move],[data-instrument],[data-exam-index],[data-connect-left],[data-connect-right]');if(!el)return;
 if(el.dataset.connectLeft!==undefined){connectLeft=+el.dataset.connectLeft;const q=route[0]==='klausur'?question(state.exam.ids[examIndex]):question(practice.queue[practice.index]);if(route[0]!=='klausur')practice.answer=capture(q);render();return}
 if(el.dataset.connectRight!==undefined){if(connectLeft===null){toast('Wähle zuerst links einen Begriff.');return}const q=route[0]==='klausur'?question(state.exam.ids[examIndex]):question(practice.queue[practice.index]),a=[...capture(q)],value=getPairs(q,route[0]==='klausur'?'exam':'practice')[+el.dataset.connectRight];a.forEach((x,i)=>{if(x===value)a[i]=''});a[connectLeft]=value;if(route[0]==='klausur'){state.exam.answers[q.id]=a;save()}else{practice.answer=a;practice.feedback=null}connectLeft=null;render();return}
 if(el.dataset.instrument){lab.instrument=el.dataset.instrument;render();return}
 if(el.dataset.examIndex!==undefined){connectLeft=null;examIndex=+el.dataset.examIndex;render();return}
 if(el.dataset.move!==undefined){const q=route[0]==='klausur'?question(state.exam.ids[examIndex]):question(practice.queue[practice.index]),a=[...capture(q)],i=+el.dataset.move,j=i+(+el.dataset.dir);if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];if(route[0]==='klausur'){state.exam.answers[q.id]=a;save()}else{practice.answer=a;practice.feedback=null}render();main.querySelector(`[data-move="${j}"][data-dir="${el.dataset.dir}"]`)?.focus();return}
 if(el.dataset.chainMove!==undefined){const i=+el.dataset.chainMove,j=i+(+el.dataset.dir);if(j<0||j>=lab.order.length)return;[lab.order[i],lab.order[j]]=[lab.order[j],lab.order[i]];lab.checked=false;render();main.querySelector(`[data-chain-move="${j}"][data-dir="${el.dataset.dir}"]`)?.focus();return}
 const action=el.dataset.action;
 switch(action){
 case'read':{const id=(topic(route[1])||topics[0]).id;state.read=state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id];save();toast(state.read.includes(id)?'Modul als gelesen gespeichert.':'Lesemarkierung entfernt.');break}
 case'practice-shuffle':resetPractice();break;
 case'practice-next':connectLeft=null;practice.index=(practice.index+1)%practice.queue.length;practice.answer=null;practice.feedback=null;practice.rubric=null;practice.reason='';break;
 case'practice-check':{const q=question(practice.queue[practice.index]),a=capture(q);if(!validAnswer(q,a)){toast('Vervollständige zuerst deine Antwort.');return}practice.answer=a;practice.feedback={score:grade(q,a)};practice.rubric=null;if(q.type!=='open')recordAnswer(q,practice.feedback.score);break}
 case'practice-self':{const q=question(practice.queue[practice.index]);if(!practice.rubric||!practice.rubric.every(Number.isInteger)){toast('Vergib zuerst Punkte für jedes Kriterium.');return}recordAnswer(q,practice.rubric.reduce((a,b)=>a+b,0),true);toast('Deine Selbsteinschätzung ist gespeichert.');break}
 case'all-errors':practice.mode='wrong';practice.topic='all';practice.type='all';resetPractice();location.hash='uebung';return;
 case'card-flip':cards.flip=!cards.flip;break;
 case'card-next':cards.index=(cards.index+1)%Math.max(1,cardQueue().length);cards.flip=false;break;
 case'card-unknown':case'card-unsure':case'card-known':{if(!cards.flip)return;const c=cardQueue()[cards.index];state.cards[c.id]=rateCard(state.cards[c.id],action.slice(5));save();cards.flip=false;if(cards.mode==='all')cards.index=(cards.index+1)%cardQueue().length;toast('Karte gespeichert.');break}
 case'exam-start':{const minutes=+$('#duration').value,difficulty=+$('#difficulty').value,ids=makeExam(questions,{difficulty});if(!Number.isInteger(minutes)||minutes<1||minutes>180){toast('Wähle eine ganze Minutenzahl zwischen 1 und 180.');return}state.exam={id:crypto.randomUUID(),phase:'running',started:Date.now(),deadline:Date.now()+minutes*60000,minutes,difficulty,ids,answers:{},reasons:{},options:{},pairs:{},orders:{}};for(const id of ids){const q=question(id);if(q.type==='mc')state.exam.options[id]=shuffle(q.options.map((_,i)=>i));if(q.type==='match'||q.type==='connect')state.exam.pairs[id]=shuffle(q.pairs.map(p=>p[1]));if(q.type==='order')state.exam.orders[id]=nonTrivialShuffle(q.items)}examIndex=0;save();break}
 case'exam-prev':connectLeft=null;examIndex=Math.max(0,examIndex-1);break;
 case'exam-next':connectLeft=null;examIndex=Math.min(state.exam.ids.length-1,examIndex+1);break;
 case'exam-confirm':$('#submit-confirm').hidden=false;$('#submit-confirm').scrollIntoView({block:'nearest'});return;
 case'exam-cancel-submit':$('#submit-confirm').hidden=true;return;
 case'exam-submit':finishExam();return;
 case'exam-new':state.exam=null;save();if(route[0]!=='klausur'){location.hash='klausur';return}break;
 case'lab-reset':lab.rate=3;break;
 case'scenario-next':lab.scenario=(lab.scenario+1)%scenarios.length;lab.revealed=false;lab.reason='';break;
 case'scenario-restrict':case'scenario-expand':if(!String(lab.reason||'').trim()){toast('Formuliere zuerst eine kurze Begründung.');return}lab.choice=action==='scenario-restrict'?'restriktiv':'expansiv';lab.revealed=true;break;
 case'chain-shuffle':lab.order=nonTrivialShuffle(chains[lab.direction]);lab.checked=false;break;
 case'chain-check':lab.checked=true;break;
 case'print':window.print();return;
 case'export':exportState();return;
 case'import-confirm':if(pendingImport){state=pendingImport;pendingImport=null;save();appearance();render();toast('Lernstand aus der Sicherung übernommen.')}return;
 case'import-cancel':pendingImport=null;$('#import-preview').innerHTML='';return;
 }render();
});
$('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'})});
$('#theme').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';appearance();save()});
$('#nav-close').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').focus()});
$('#menu').addEventListener('click',()=>{const on=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(on))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();if(route[0]==='glossar')$('#glossary-search').focus();else{location.hash='glossar';setTimeout(()=>$('#glossary-search')?.focus(),0)}}});
setInterval(()=>{if(state.exam?.phase!=='running')return;if(Date.now()>=state.exam.deadline)finishExam(true);else if($('#timer'))$('#timer').textContent=timeLeft(state.exam)},1000);
function exportState(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`geldpolitik-lernstand-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('JSON-Sicherung erstellt.')}
let pendingImport=null;
async function previewImport(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('Die Datei ist zu groß.');const s=JSON.parse(await file.text());if(s.version!==1||!Array.isArray(s.read)||!s.answers||!s.cards||!Array.isArray(s.exams)||!s.notes)throw Error('Keine gültige Lernstand-Sicherung.');if(s.read.some(id=>!topic(id))||Object.entries(s.answers).some(([id,a])=>!question(id)||!Number.isFinite(a.score)||a.score<0||a.score>question(id).points)||!['dark','light'].includes(s.theme)||!['financial','studio','editorial'].includes(s.design))throw Error('Die Sicherung enthält ungültige Lernwerte.');if(s.exams.some(e=>!validExam(e))||(s.exam&&!validExam(s.exam)))throw Error('Ungültige Klausurdaten.');pendingImport={...load({getItem:()=>JSON.stringify(s)}),notes:Object.fromEntries(Object.entries(s.notes).filter(([k,v])=>typeof v==='string'))};$('#import-preview').innerHTML=`<div class="confirm-panel"><h3>Sicherung übernehmen?</h3><p>${s.read.length} gelesene Module, ${Object.keys(s.answers).length} gespeicherte Antworten und ${s.exams.length} Klausuren. Der aktuelle lokale Lernstand wird ersetzt.</p><div class="actions">${button('Lernstand ersetzen','import-confirm',true)}${button('Abbrechen','import-cancel')}</div></div>`}catch(e){toast(e.message||'Sicherung konnte nicht gelesen werden.')}}
function validExam(e){
 if(!e||typeof e.id!=='string'||!/^[a-z0-9-]{10,80}$/i.test(e.id)||!Array.isArray(e.ids)||e.ids.length!==12||new Set(e.ids).size!==12||!e.ids.every(id=>question(id))||!e.answers||typeof e.answers!=='object'||!Number.isFinite(e.started)||!Number.isFinite(e.deadline)||!Number.isInteger(e.minutes)||e.minutes<1||e.minutes>180||!['running','review'].includes(e.phase)||!e.options||!e.pairs||!e.orders)return false;
 if(e.phase==='review'&&!Number.isFinite(e.ended))return false;
 return e.ids.every(id=>{const q=question(id);if(q.type==='mc'&&(!Array.isArray(e.options[id])||e.options[id].length!==q.options.length||e.options[id].some(v=>!Number.isInteger(v)||v<0||v>=q.options.length)))return false;if((q.type==='match'||q.type==='connect')&&(!Array.isArray(e.pairs[id])||e.pairs[id].length!==q.pairs.length||e.pairs[id].some(v=>!q.pairs.some(p=>p[1]===v))))return false;if(q.type==='order'&&(!Array.isArray(e.orders[id])||e.orders[id].length!==q.items.length||e.orders[id].some(v=>!q.items.includes(v))))return false;if(q.type==='open'&&e.rubrics?.[id]&&(!Array.isArray(e.rubrics[id])||e.rubrics[id].length!==q.criteria.length||e.rubrics[id].some(v=>v!==null&&![0,1,2].includes(v))))return false;return true});
}
window.addEventListener('beforeprint',()=>{main.querySelectorAll('textarea').forEach(x=>{const d=document.createElement('div');d.className='print-value';d.textContent=x.value||'–';x.after(d)})});
window.addEventListener('afterprint',()=>main.querySelectorAll('.print-value').forEach(x=>x.remove()));
