if(state.exam&&!validExam(state.exam))state.exam=null;state.exams=state.exams.filter(validExam);
state.read=state.read.filter(id=>topic(id));state.answers=Object.fromEntries(Object.entries(state.answers).filter(([id,a])=>question(id)&&Number.isFinite(a?.score)));
